<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { AlertTriangle, Check, Copy, LockKeyhole, PencilLine, Sparkles, UserRoundCheck } from 'lucide-vue-next'
import { suggestedScores } from '../utils/arabic.js'
import { useAuthStore } from '../stores/auth.js'
import { useRoomStore } from '../stores/room.js'
import { finalizeRound, initializeReview, setReviewPosition, setReviewScore, watchAnswers, watchReviewState, watchRound } from '../services/game.js'
import CharacterAvatar from '../components/common/CharacterAvatar.vue'
import { audioManager } from '../audio/manager.js'
import { syncRoomRoute } from '../utils/roomRoute.js'

const route=useRoute(),router=useRouter(),auth=useAuthStore(),roomStore=useRoomStore();const active=ref(0),round=ref(null),prepared=ref([]),answers=ref([]),reviewState=ref(null),demoScores=ref({}),finalized=ref(false),busy=ref(false),error=ref('');let stopRound,stopAnswers,stopReview,releaseRoom,reviewInitialized=false
const isDemo=computed(()=>route.name==='review'),code=computed(()=>String(route.params.code||'').toUpperCase()),roundId=computed(()=>String(route.params.roundId||'')),role=computed(()=>isDemo.value?'host':roomStore.isHost?'host':'player')
const demoCategories=[{label:'ولد',entries:[{uid:'a',player:'أحمد',avatar:'character-01',answer:'محمود'},{uid:'k',player:'كريم',avatar:'character-06',answer:'محمود'},{uid:'m',player:'مريم',avatar:'character-02',answer:'مصطفى'}]},{label:'بلاد',entries:[{uid:'a',player:'أحمد',avatar:'character-01',answer:'مصر'},{uid:'k',player:'كريم',avatar:'character-06',answer:'مِصْر'},{uid:'m',player:'مريم',avatar:'character-02',answer:'المغرب'}]}],colors=['#7555E8','#FF7F91','#3BC7AD','#E9AE15']
function buildCategories(){const source=isDemo.value?demoCategories:(roomStore.room?.categories||[]).map(label=>({label,entries:roomStore.players.map(player=>{const answer=answers.value.find(a=>a.uid===player.uid);return{uid:player.uid,player:player.nickname,avatar:player.avatar,answer:answer?.values?.[label]||''}})}));prepared.value=source.map((category,categoryIndex)=>({id:`c-${categoryIndex}`,label:category.label,color:colors[categoryIndex%colors.length],entries:suggestedScores(category.entries).map((entry,playerIndex)=>({...entry,id:`${entry.uid}::${category.label}`,categoryIndex,playerIndex}))}))}
onMounted(async()=>{if(isDemo.value){buildCategories();return}await auth.initialize();releaseRoom=roomStore.subscribe(code.value);stopRound=watchRound(code.value,roundId.value,value=>{round.value=value;finalized.value=value?.status==='finalized'},e=>error.value=e.message);stopAnswers=watchAnswers(code.value,roundId.value,data=>{answers.value=data;buildCategories()},e=>error.value=e.message);stopReview=watchReviewState(code.value,roundId.value,state=>{reviewState.value=state;if(state)active.value=state.activeCategory||0},e=>error.value=e.message)})
onBeforeUnmount(()=>{releaseRoom?.();stopRound?.();stopAnswers?.();stopReview?.()});watch(()=>[roomStore.room,roomStore.players],buildCategories,{deep:true});watch(active,()=>window.scrollTo({top:0,behavior:'smooth'}))
watch(()=>roomStore.room,room=>{if(!isDemo.value)syncRoomRoute(router,route.path,room,code.value)},{deep:true})
watch(()=>roomStore.isHost,async value=>{if(value&&!reviewInitialized&&!isDemo.value){reviewInitialized=true;try{await initializeReview(code.value,roundId.value)}catch(e){error.value=e.message}}},{immediate:true})
const scoreFor=entry=>isDemo.value?(demoScores.value[entry.id]??null):(reviewState.value?.scores?.[entry.uid]?.[entry.categoryIndex]??null)
const current=computed(()=>prepared.value[active.value]||{entries:[],label:''}),reviewed=computed(()=>prepared.value.flatMap(c=>c.entries).filter(entry=>scoreFor(entry)!==null).length),totalAnswers=computed(()=>prepared.value.reduce((sum,c)=>sum+c.entries.length,0)),categoryTotal=computed(()=>current.value.entries.reduce((sum,e)=>sum+Number(scoreFor(e)||0),0)),playerTotals=computed(()=>prepared.value.flatMap(c=>c.entries).reduce((acc,e)=>({...acc,[e.player]:(acc[e.player]||0)+Number(scoreFor(e)||0)}),{}))
async function chooseScore(entry,score){if(finalized.value||role.value!=='host')return;if(isDemo.value){demoScores.value={...demoScores.value,[entry.id]:score};return}try{await setReviewScore(code.value,roundId.value,entry.uid,entry.categoryIndex,score)}catch(e){error.value=e.message}}
async function selectCategory(index){if(role.value!=='host')return;if(isDemo.value){active.value=index;return}try{await setReviewPosition(code.value,roundId.value,index,0)}catch(e){error.value=e.message}}
function nextUnreviewed(){const category=prepared.value.find(c=>c.entries.some(e=>scoreFor(e)===null));if(category)selectCategory(category.entries[0]?.categoryIndex||0)}
async function finalize(){if(isDemo.value){finalized.value=true;audioManager.play('results');return}busy.value=true;error.value='';try{await finalizeRound(code.value,roundId.value);const finalRound=(roomStore.room?.roundNumber||0)>=(roomStore.room?.totalRounds||0);audioManager.playOnce(finalRound?'winner':'results',`results:${code.value}:${roundId.value}`)}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><div class="review-page"><header class="review-topbar"><RouterLink :to="isDemo?'/notebook':`/room/${code}`" class="back-link light">رجوع للقعدة</RouterLink><div><LockKeyhole/> الجولة اتقفلت — الإجابات للقراءة بس</div></header>
<main class="review-shell"><section class="review-heading"><div><span class="sticker"><PencilLine/> تصحيح الجولة {{ round?.number||3 }}</span><h1>راجع كراسات الحرفنجية</h1><p>{{role==='host'?'الاقتراح بيساعدك، وإنت صاحب القرار الأخير.':'بتشوف تصحيح الأدمن مباشر لحظة بلحظة.'}}</p></div><div class="review-progress"><strong>{{reviewed}} <small>/ {{totalAnswers}}</small></strong><span>إجابة اتراجعت</span><div><i :style="{width:`${totalAnswers?reviewed/totalAnswers*100:0}%`}"/></div></div></section>
<nav class="category-tabs"><button v-for="(category,index) in prepared" :key="category.id" :disabled="role!=='host'" :class="{active:active===index,complete:category.entries.every(e=>scoreFor(e)!==null)}" :style="{'--tab-color':category.color}" @click="selectCategory(index)"><Check v-if="category.entries.every(e=>scoreFor(e)!==null)"/>{{category.label}}<b>{{category.entries.reduce((sum,e)=>sum+Number(scoreFor(e)||0),0)}}</b></button></nav>
<section class="correction-sheet"><div class="correction-title"><div><small>التصنيف</small><h2>{{current.label}}</h2></div><div class="round-letter"><small>حرف</small><b>{{round?.letter||'م'}}</b></div><p><Sparkles/> المتكرر متعلّم عليه تلقائي</p></div><div class="review-table-head"><span>اللاعب</span><span>الإجابة</span><span>المقترح</span><span>قرار الأدمن</span></div>
<article v-for="entry in current.entries" :key="entry.id" class="answer-review" :class="{duplicate:entry.duplicate,reviewed:scoreFor(entry)!==null,'active-review':reviewState?.activeCategory===entry.categoryIndex&&reviewState?.activeEntry===entry.playerIndex}"><div class="review-player"><CharacterAvatar :id="entry.avatar" :size="44"/><b>{{entry.player}}</b></div><div class="review-answer"><b v-if="entry.answer">{{entry.answer}}</b><em v-else>مفيش إجابة</em><small v-if="entry.duplicate"><Copy/> إجابة متكررة</small></div><div class="suggested-score" :class="`score-${entry.suggested}`"><small>المقترح</small><b>{{entry.suggested}}</b></div><div class="score-buttons"><button v-for="score in [0,5,10]" :key="score" :disabled="finalized||role!=='host'" :class="{selected:scoreFor(entry)===score}" @click="chooseScore(entry,score)">{{score}}</button></div></article><footer class="category-summary"><span>مجموع التصنيف</span><b>{{categoryTotal}} نقطة</b></footer></section>
<section class="round-summary"><div><UserRoundCheck/><span>مجموع الجولة لكل لاعب</span></div><ul><li v-for="(score,player) in playerTotals" :key="player"><span>{{player}}</span><b>{{score}}</b></li></ul></section><aside v-if="reviewed<totalAnswers" class="review-warning"><AlertTriangle/><span>لسه {{totalAnswers-reviewed}} إجابة محتاجة تأكيد.</span><button v-if="role==='host'" @click="nextUnreviewed">روح لأول إجابة</button></aside><p v-if="error" class="error-message">{{error}}</p><div v-if="role==='host'" class="finalize-bar"><span>بعد الاعتماد النقط مش هتتغير</span><button class="btn btn-primary btn-lg" :disabled="reviewed<totalAnswers||finalized||busy" @click="finalize">{{busy?'بنعتمد...':'اعتماد نتيجة الجولة'}}</button></div></main></div></template>
